duckdb -c "CREATE TABLE main.priority_jobs_snapshot (job_id INT PRIMARY KEY, job_title_short VARCHAR, company_name VARCHAR, job_posted_date DATE, salary_year_avg DOUBLE, priority_level INT, updated_at TIMESTAMP); INSERT INTO main.priority_jobs_snapshot VALUES (1, 'Data Engineer', 'Acme', DATE '2024-01-01', 120000, 2, TIMESTAMP '2024-01-01 00:00:00'); CREATE OR REPLACE TEMP TABLE source_priority_jobs AS SELECT 1 AS job_id, 'Data Engineer' AS job_title_short, 'Acme' AS company_name, DATE '2024-01-01' AS job_posted_date, 120000 AS salary_year_avg, 1 AS priority_level, CURRENT_TIMESTAMP AS updated_at; MERGE INTO main.priority_jobs_snapshot AS snapshot USING source_priority_jobs AS source ON snapshot.job_id = source.job_id WHEN MATCHED AND snapshot.priority_level IS DISTINCT FROM source.priority_level THEN UPDATE SET job_title_short = source.job_title_short, company_name = source.company_name, job_posted_date = source.job_posted_date, salary_year_avg = source.salary_year_avg, priority_level = source.priority_level, updated_at = source.updated_at WHEN NOT MATCHED THEN INSERT (job_id, job_title_short, company_name, job_posted_date, salary_year_avg, priority_level, updated_at) VALUES (source.job_id, source.job_title_short, source.company_name, source.job_posted_date, source.salary_year_avg, source.priority_level, source.updated_at); SELECT * FROM main.priority_jobs_snapshot;"